def max_energy(beads):
    n = len(beads)
    if n < 3:
        return 0

    # Add a bead to simulate the circular nature
    beads = beads + [beads[0]]

    # dp[i][j] will store the maximum energy obtainable from merging beads from i to j
    dp = [[0] * n for _ in range(n)]

    # Iterate over the length of the subarray to consider
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            for k in range(i + 1, j + 1):
                dp[i][j] = max(dp[i][j], dp[i][k-1] + dp[k][j] + beads[i] * beads[k] * beads[j + 1])

    return dp[0][n - 1]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        sign = '-' if coeff < 0 else '+'
        coeff_str = str(abs(coeff)) if abs(coeff) != 1 or degree == 0 else ''
        if degree == 0:
            var_str = ''
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = f'x^{degree}'
        if not terms:
            # First term should not have a leading '+'
            terms.append(f'{coeff_str}{var_str}')
        else:
            terms.append(f'{sign}{coeff_str}{var_str}')
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for enc, orig in zip(encoded, original):
        if enc in mapping:
            if mapping[enc] != orig:
                return "Failed"
        else:
            mapping[enc] = orig

    if len(mapping) != len(set(original)):
        return "Failed"

    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded_message)

def largest_prime_factor(n: int) -> int:
    # Start checking from the smallest prime number
    factor = 2
    while factor * factor <= n:
        if n % factor == 0:
            # If a factor is found, return the other factor
            return n // factor
        factor += 1
    # If no factors are found, n itself is a prime number
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    # Base cases
    if n < k * x:
        return 0
    if k == 1:
        return 1 if n >= x else 0

    # Recursive case
    # Option 1: Exclude the smallest part x, so we need to partition n - x into k parts, each at least x
    # Option 2: Include at least one part > x, so we need to partition n into k parts, each at least x + 1
    return count_partitions(n - x, k - 1, x) + count_partitions(n - x, k, x + 1)

