def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]

    # Base case: if last is 1, only the sequence [1] is valid
    if last == 1:
        return 1

    count = 1  # Count the sequence consisting of the number itself
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)

    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    count = 0
    quotient = y0 // x0

    for a in range(1, int(quotient**0.5) + 1):
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            continue

        for src, tgt in rules:
            # Find all possible positions to apply the rule
            start = 0
            while start < len(current):
                start = current.find(src, start)
                if start == -1:
                    break
                # Apply the rule
                new_string = current[:start] + tgt + current[start + len(src):]
                if new_string == B:
                    return steps + 1
                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, steps + 1))
                start += 1

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

