def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a DP array where dp[i] will be True if a subset with volume i can be formed
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: a subset with volume 0 is always possible (empty subset)

    # Iterate over each item
    for volume in volumes:
        # Update the dp array from right to left
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be achieved which is less than or equal to V
    max_achievable_volume = 0
    for i in range(V, -1, -1):
        if dp[i]:
            max_achievable_volume = i
            break

    # The minimum remaining space is the total capacity minus the maximum achievable volume
    return V - max_achievable_volume

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i][j - 1]) % MOD
            if j - a[i - 1] - 1 >= 0:
                dp[i][j] = (dp[i][j] - dp[i - 1][j - a[i - 1] - 1] + MOD) % MOD

    return dp[n][m]

def mod_inverse(a, b):
    def extended_gcd(aa, bb):
        if bb == 0:
            return aa, 1, 0
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return gcd, x, y

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None  # Modular inverse doesn't exist if a and b are not coprime
    else:
        return x % b  # Ensure the result is positive

def find_most_unhappy_day(schedule) -> int:
    max_unhappiness = 0
    most_unhappy_day = 0
    threshold = 8

    for i, (school_hours, extra_hours) in enumerate(schedule, 1):
        total_hours = school_hours + extra_hours
        if total_hours > threshold:
            unhappiness = total_hours - threshold
            if unhappiness > max_unhappiness:
                max_unhappiness = unhappiness
                most_unhappy_day = i

    return most_unhappy_day

def jinjin_savings_plan(budgets: List[int]) -> int:
    pocket_money_per_month = 300
    savings_rate = 0.2
    total_savings = 0

    for month, budget in enumerate(budgets, start=1):
        remaining_after_expenses = pocket_money_per_month - budget
        if remaining_after_expenses < 0:
            return -month
        savings = (remaining_after_expenses // 100) * 100
        total_savings += savings

